/*----------------------------------------------------------------------------*/
/* functions and function style macros                                        */
/*----------------------------------------------------------------------------*/
#if ( SAMPLE_FLS_ENABLE != FALSE )
void SampleFls( void ) {

    /*
     * 3.2.3 Flash module sample function
     */

    /* Fls initialization operation */
    Fls_Init( &FlsConfigData );

    /* Set to fast mode */
    Fls_SetMode( MEMIF_MODE_FAST );

    /* Flash Erase, Blank Check, Write, Read and Compare sequence */

    /* Prepare erase job */
    Fls_Erase( 0x01C00, 4096U );

    /* Execute erasing operation in period processing */
    Fls_MainFunction();
    Fls_MainFunction();
    Fls_MainFunction();

    /* Call completion notification from periodic processing ( Fee_JobEndNotification function ) */
    Fls_MainFunction();

    /* Getting Job result */
    SampleFls_EraseResult = Fls_GetJobResult();

    /* Prepare blank check job */
    Fls_BlankCheck( 0x01C00, 4096U );

    /* Execute blank check operation in period processing */
    Fls_MainFunction();

    /* Getting Job result */
    SampleFls_BlankChkResult = Fls_GetJobResult();

    /* Prepare write job */
    Fls_Write( 0x01C00, &SampleFls_WriteData[0], 1024U );

    /* Execute writing operation in period processing */
    Fls_MainFunction();
    Fls_MainFunction();
    Fls_MainFunction();

    /* Call completion notification from periodic processing ( Fee_JobEndNotification function ) */
    Fls_MainFunction();

    /* Getting Job result */
    SampleFls_WriteResult = Fls_GetJobResult();

    /* Prepare reading job */
    Fls_Read( 0x01C00, &SampleFls_ReadData[0], 1024U );

    /* Execute reading operation in period processing */
    Fls_MainFunction();
    Fls_MainFunction();
    Fls_MainFunction();

    /* Call completion notification from periodic processing ( Fee_JobEndNotification function ) */
    Fls_MainFunction();

    /* Getting Job result */
    SampleFls_ReadResult = Fls_GetJobResult();

    /* Prepare compare job */
    Fls_Compare( 0x01C00, &SampleFls_CompareData[0], 1024U );

    /* Execute comparing operation in period processing */
    Fls_MainFunction();

    /* Getting Job result */
    SampleFls_CompareResult = Fls_GetJobResult();

    /*
     * Flash canceling a running Job
     */
    Fls_Read( 0x01C00, &SampleFls_ReadData[0], 1024U );
    Fls_Cancel();

    /* Getting Job result */
    SampleFls_CancelResult = Fls_GetJobResult();

    /*
     * Flash get status
     */
    SampleFls_Status = Fls_GetStatus();

    /* End of program */
    while ( TRUE ) {
        FUNC_NO_OPERATION;
    }
}
#endif

